using Microsoft.EntityFrameworkCore;

// Cosmos DB provider — EF Core 9 breaking changes applied
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Default discriminator property renamed from
        // "Discriminator" to "$type" in EF Core 9. Existing documents use
        // the old name, so configure it explicitly to preserve compatibility.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: id property no longer includes the discriminator
        // (e.g. "123" instead of "Session|123"). Existing documents have the
        // old compound format. Preserve it so existing data remains accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Title { get; set; } = null!;
}

// Breaking change 3: Sync I/O is no longer supported on the Cosmos DB provider.
// Synchronous methods like ToList() and SaveChanges() now throw.
// All Cosmos DB queries and saves must use async equivalents.
class CosmosRepository
{
    // BEFORE (throws in EF Core 9):
    //   var sessions = db.Sessions.ToList();
    //   db.SaveChanges();
    //
    // AFTER:
    async Task<List<Session>> GetSessionsAsync(CosmosDbContext db)
    {
        return await db.Sessions.ToListAsync();
    }

    async Task SaveAsync(CosmosDbContext db)
    {
        await db.SaveChangesAsync();
    }
}

